/* @lc app=leetcode id=1391 lang=kotlin */ class Solution { fun hasValidPath(grid: Array<IntArray>): Boolean = listOf(listOf<Int>(), listOf(0, 1), listOf(2, 3), listOf(0, 3), listOf(1, 3), listOf(0, 2), listOf(1, 2)).let { t -> listOf(0, 0, -1, 1).let { dr -> listOf(-1, 1, 0, 0).let { dc -> HashSet<Pair<Int, Int>>().also { it.add(0 to 0) }.let { seen -> generateSequence(listOf(0 to 0)) { f -> f.flatMap { (r, c) -> t[grid[r][c]].map { d -> Triple(r + dr[d], c + dc[d], d) } }.filter { (r, c, d) -> r in grid.indices && c in grid[0].indices && (d xor 1) in t[grid[r][c]] }.map { it.first to it.second }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.flatten().any { it == grid.size - 1 to grid[0].size - 1 } } } } } }